const XLSX = require('xlsx');
const wb = XLSX.readFile('data/travel_expenses.xlsx');
for (const name of wb.SheetNames) {
    console.log('=== Sheet: ' + name + ' ===');
    const ws = wb.Sheets[name];
    const data = XLSX.utils.sheet_to_json(ws, { header: 1 });
    data.forEach(row => console.log(row.join(' | ')));
    console.log();
}
"

cd /workspace/testbed && node -e "
const XLSX = require('xlsx');
const wb = XLSX.readFile('data/travel_expenses.xlsx');
const ws = wb.Sheets['Travel'];
const data = XLSX.utils.sheet_to_json(ws);
// Get Las Vegas hotel and car rental entries
const lvHotel = data.filter(r => r.Type === 'Hotel' && (r['Route/Location'] || '').includes('Las Vegas'));
const lvCar = data.filter(r => r.Type === 'Car Rental' && (r['Route/Location'] || '').includes('Las Vegas'));
console.log('=== Las Vegas Hotels ===');
lvHotel.forEach(r => console.log(JSON.stringify(r, null, 2)));
console.log('=== Las Vegas Car Rentals ===');
lvCar.forEach(r => console.log(JSON.stringify(r, null, 2)));
"

